{
    public static class ImmanuelKant
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "The wish to talk to God is absurd. We cannot talk to one we cannot comprehend - and we cannot comprehend God; we can only believe in Him.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "Religion is too important a matter to its devotees to be a subject of ridicule. If they indulge in absurdities, they are to be pitied rather than ridiculed.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "The body is a temple.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "Out of the crooked timber of humanity, no straight thing was ever made.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "Beneficence is a duty. He who often practices this, and sees his beneficent purpose succeed, comes at last really to love him whom he has benefited.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "Apart from moral conduct, all that man thinks himself able to do in order to become acceptable to God is mere superstition and religious folly.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "Have patience awhile; slanders are not long-lived. Truth is the child of time; erelong she shall appear to vindicate thee.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "The death of dogma is the birth of morality.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "By a lie a man throws away and, as it were, annihilates his dignity as a man.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "It is much more natural and reasonable to assume that a nebula is not a unique and solitary sun, but a system of numerous suns.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "We see that scattered through space out to infinite distances, there exist similar systems of stars [nebulous stars, nebulæ], and that creation, in the whole extent of its infinite grandeur, is everywhere organized into systems whose members are in relation with one another.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "A vast field lies open to discoveries, and observations alone will give the key.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "As the analysis of a substantial composite terminates only in a part which is not a whole, that is, in a simple part, so synthesis terminates only in a whole which is not a part, that is, the world.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "The mind intent upon resolving as well as compounding the concept of a composite demands and presumes boundaries in which it may acquiesce in the former as well as in the latter direction.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "Percepts and phenomena which precedes the logical use of the intellect is called appearance, while the reflex knowledge originating from several appearances compared by the intellect is called experience.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "The sensuous may be exceedingly distinct, while intellectual concepts are extremely confused.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "Now the maximum of perfection is called ideal, by Plato, Idea - for instance, his Idea of a Republic - and is the principle of all that is contained under the general notion of any perfection, inasmuch as the lesser grades are not thought determinable but by limiting the maximum.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "The concept of space is not abstracted from external sensations.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "The concept of space, therefore, is a pure intuition, being a singular concept, not made up by sensations, but itself the fundamental form of all external sensation.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "Nature, therefore, is subject with absolute precision to all the precepts of geometry as to all the properties of space there demonstrated, this being the subjective condition, not hypothetically but intuitively given, of every phenomenon in which nature can ever be revealed to the senses.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "Space is employed as the type even of the concept of time itself, representing it by a line, and its limits - moments - by points.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "The question of the principle of the form of the intelligible world turns, therefore, upon making apparent in what manner it is possible for several substances to be in mutual commerce, and for this reason to pertain to the same whole, which is called world.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "A whole from necessary substances is impossible. The whole, therefore, of substances is a whole of contingent things, and the world consists essentially of only contingent things.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "Several actual worlds without one another are not, therefore, impossible by the very concept, as Wolf hastily concluded from the notion of a complex or multiplicity which he deemed sufficient to a whole, as such, but only on condition that there exist but one necessary cause of all things.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "A spurious axiom of the first class is: 'Whatever is, is somewhere and sometime.'", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "They cudgel their brains with absurd questions, such as, for instance, why God did not make the world many centuries earlier.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "The prejudices of the second species, since they impose upon the intellect by the sensual conditions restricting the mind if it wishes in certain cases to attain to what is intellectual, lurk more deeply.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "I freely admit that the remembrance of David Hume was the very thing that many years ago first interrupted my dogmatic slumber and gave a completely different direction to my researches in the field of speculative philosophy.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "Enlightenment is man's leaving his self-caused immaturity. Immaturity is the incapacity to use one's intelligence without the guidance of another.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "Such immaturity is self-caused if it is not caused by lack of intelligence, but by lack of will determination and courage to use one's intelligence without being guided by another.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "Sapere Aude! Have the courage to use your own intelligence! is therefore the motto of the enlightenment.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "It is so easy to be immature. If I have a book to serve as my understanding, a pastor to serve as my conscience, a physician to determine my diet for me, and so on, I need not exert myself at all.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "I need not think, if only I can pay: others will readily undertake the irksome work for me.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "Through laziness and cowardice a large part of mankind, even after nature has freed them from alien guidance, gladly remain immature.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "It is because of laziness and cowardice that it is so easy for others to usurp the role of guardians.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "It is so comfortable to be a minor!", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "It is difficult for the isolated individual to work himself out of the immaturity which has become almost natural for him.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "He has even become fond of it and for the time being is incapable of employing his own intelligence, because he has never been allowed to make the attempt.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "Statutes and formulas, these mechanical tools of a serviceable use, or rather misuse, of his natural faculties, are the ankle-chains of a continuous immaturity.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "Whoever threw it off would make an uncertain jump over the smallest trench because he is not accustomed to such free movement.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "Therefore there are only a few who have pursued a firm path and have succeeded in escaping from immaturity by their own cultivation of the mind.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "A public can only arrive at enlightenment slowly.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "Through revolution, the abandonment of personal despotism may be engendered and the end of profit-seeking and domineering oppression may occur, but never a true reform of the state of mind.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "Instead, new prejudices, just like the old ones, will serve as the guiding reins of the great, unthinking mass.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "All that is required for this enlightenment is freedom; and particularly the least harmful of all that may be called freedom, namely, the freedom for man to make public use of his reason in all matters.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "But I hear people clamor on all sides: Don't argue! The officer says: Don't argue, drill! The tax collector: Don't argue, pay! The pastor: Don't argue, believe!", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "The public use of a man's reason must be free at all times, and this alone can bring enlightenment among men...", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "Whatever concept one may hold, from a metaphysical point of view, concerning the freedom of the will, certainly its appearances, which are human actions, like every other natural event are determined by universal laws.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "One cannot suppress a certain indignation when one sees men's actions on the great world-stage and finds, beside the wisdom that appears here and there among individuals, everything in the large woven together from folly, childish vanity, even from childish malice and destructiveness.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "In the end, one does not know what to think of the human race, so conceited in its gifts.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "All natural capacities of a creature are destined to evolve completely to their natural end.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "Reason does not work instinctively, but requires trial, practice, and instruction in order to gradually progress from one level of insight to another.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "Nature has willed that man should, by himself, produce everything that goes beyond the mechanical ordering of his animal existence, and that he should partake of no other happiness or perfection than that which he himself, independently of instinct, has created by his own reason.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "Nature has no[t] done anything in vain, and in the use of means to her goals she is not prodigal.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "Her giving to man reason and the freedom of the will which depends upon it is clear indication of her purpose.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "Man accordingly was not to be guided by instinct, not nurtured and instructed with ready-made knowledge; rather, he should bring forth everything out of his own resources.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "The means employed by Nature to bring about the development of all the capacities of men is their antagonism in society, so far as this is, in the end, the cause of a lawful order among men.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "The greatest problem for the human race, to the solution of which Nature drives man, is the achievement of a universal civic society which administers law among men.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "The master is himself an animal, and needs a master.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "Let him begin it as he will, it is not to be seen how he can procure a magistracy which can maintain public justice and which is itself just, whether it be a single person or a group of several elected persons.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "For each of them will always abuse his freedom if he has none above him to exercise force in accord with the laws.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "The highest master should be just in himself, and yet a man.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "This task is therefore the hardest of all; indeed, its complete solution is impossible, for from such crooked wood as man is made of, nothing perfectly straight can be built.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "That it is the last problem to be solved follows also from this: it requires that there be a correct conception of a possible constitution, great experience gained in many paths of life, and - far beyond these - a good will ready to accept such a constitution.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "Three such things are very hard, and if they are ever to be found together, it will be very late and after many vain attempts.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "The problem of establishing a perfect civic constitution is dependent upon the problem of a lawful external relation among states and cannot be solved without a solution of the latter problem.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "The friction among men, the inevitable antagonism, which is a mark of even the largest societies and political bodies, is used by Nature as a means to establish a condition of quiet and security.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "In a league of nations, even the smallest state could expect security and justice, not from its own power and by its own decrees, but only from this great league of nations ... from a united power acting according to decisions reached under the laws of their united will.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "Is it reasonable to assume a purposiveness in all the parts of nature and to deny it to the whole?", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "To a high degree we are, through art and science, cultured. We are civilized - perhaps too much for our own good - in all sorts of social grace and decorum. But to consider ourselves as having reached morality - for that, much is lacking.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "The ideal of morality belongs to culture; its use for some simulacrum of morality in the love of honor and outward decorum constitutes mere civilization.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "So long as states waste their forces in vain and violent self-expansion, and thereby constantly thwart the slow efforts to improve the minds of their citizens by even withdrawing all support from them, nothing in the way of a moral order is to be expected.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "For such an end, a long internal working of each political body toward the education of its citizens is required.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "Everything good that is not based on a morally good disposition, however, is nothing but pretense and glittering misery.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "In such a condition the human species will no doubt remain until, in the way I have described, it works its way out of the chaotic conditions of its international relations.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "A philosophical attempt to work out a universal history according to a natural plan directed to achieving the civic union of the human race must be regarded as possible and, indeed, as contributing to this end of Nature.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "There is nothing at all in the world, or even out of it, that can without limitation be considered good except a good will.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "I ought never to act except in such a way that I could also will that my maxim should become a universal law.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "I ask myself only: can you also will that your maxim become a universal law?", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "Morality is thus the relation of actions to the autonomy of the will, that is, to a possible giving of universal law through its maxims.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "An action that can coexist with the autonomy of the will is permitted; one that does not accord with it is forbidden.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "A will whose maxims necessarily harmonize with the laws of autonomy is a holy, absolutely good will.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "The dependence upon the principle of autonomy of a will that is not absolutely good (moral necessitation) is obligation.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "This, accordingly, cannot be attributed to a holy being.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "The objective of an action from obligation is called duty.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "Act so as to treat humanity, whether in your own person or in that of another, at all times also as an end, and not only as a means.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "In the kingdom of ends everything has either a price or a dignity. What has a price can be replaced by something else as its equivalent; what on the other hand is raised above all price and therefore admits of no equivalent has a dignity.", Author = "Immanuel Kant" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Immanuel_Kant", Text = "Here as elsewhere human reason in its pure use, so long as it was not critically examined, has first tried all possible wrong ways before it succeeded in finding the one true way.", Author = "Immanuel Kant" },
        };
    }
}